import torch
import torch.nn as nn

class PINN(nn.Module):
    def __init__(self):
        super().__init__() # fully connected feedforward network
        self.net = nn.Sequential(
            nn.Linear(2, 50), # eisodos 2 (x,y) hidden layer 1: 50 nevrones
            nn.Tanh(),  # synartisi energopoihshs Tahn 
            nn.Linear(50, 50), # hidden layer 2: 50 nevrones
            nn.Tanh(),
            nn.Linear(50, 1) # eksodos u(x,y)
        )

    def forward(self, x):
        return self.net(x)

class PINN_Large(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(2, 100),
            nn.Tanh(),
            nn.Linear(100, 100),
            nn.Tanh(),
            nn.Linear(100, 100),
            nn.Tanh(),
            nn.Linear(100, 1)
        )

    def forward(self, x):
        return self.net(x)


